Definition qcb_ms : machine_state :=
  MS (mkR (Z_to_bv 64 0xa3060) (Z_to_bv 64 (C - 112)) gp (Z_to_bv 64 tpA) t0 t1 t2 s0 s1 (Z_to_bv 64 (C - 104)) (Z_to_bv 64 M)
          a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (Z_to_bv 64 qcbrec_entry) fc None m (seg_rom asegs).

Definition qcb_out : machine_state -> Prop :=
  fun ms => exists (t0' t1' t2' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m1 : mem),
    ms = MS (mkR (Z_to_bv 64 0xa3060) (Z_to_bv 64 (C - 112)) gp (Z_to_bv 64 tpA) t0' t1' t2' s0 s1 (Z_to_bv 64 (T + 208))
                 (Z_to_bv 64 INST) (Z_to_bv 64 c) (Z_to_bv 64 AB) a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6')
            F (Z_to_bv 64 cdealloc_entry) fc None m1 (seg_rom asegs)
    /\ ARTc (set_st Σ c i CkIdle) m1 /\ munch (W_QCB AB M n T C) m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1
    /\ stk asegs m1 lo (C - 112) /\ rt_pres (live Σ) (frames Σ) (C - 112) m m1.

